#!/usr/bin/env python3
"""Aggregate diagnostic query/PIT observations without subtracting percentiles."""
import json,pathlib,statistics,sys,importlib.util
spec=importlib.util.spec_from_file_location('p2c',pathlib.Path(__file__).with_name('summarize-p2c.py'));p2c=importlib.util.module_from_spec(spec);spec.loader.exec_module(p2c)
def stat(v):
 v=sorted(v)
 return {'n':len(v),'mean':statistics.mean(v),'p50':v[(len(v)-1)//2],'p95':v[int((len(v)-1)*.95)],'min':v[0],'max':v[-1]}
def run(path):
 root=path/'results';data=json.loads((root/'ablations.json').read_text());rows=[]
 resources=p2c.lines(root/'ablation-resources.jsonl');bulk=p2c.lines(root/'ablation-projection-p2d-events.jsonl')
 reference=data['results'][0]['samples'][3]['ids_hash'] if data['results'][0]['variant']!='simple-sort' else None
 for r in data['results']:
  s=[x for x in r['samples'] if not x['warmup']];assert len(s)==100
  a,b=r['before'],r['after'];seconds=(r['queryEnded']-r['started'])/1000
  cpu=(b['process']['cpu']['total_in_millis']-a['process']['cpu']['total_in_millis'])/1000
  counters={group:{k:v-a['indices'][group].get(k,0) for k,v in b['indices'][group].items() if isinstance(v,(int,float)) and not isinstance(v,bool)} for group in ['indexing','refresh','merges','flush']}
  rs=[x for x in resources if r['started']/1000<=x['time']<=r['queryEnded']/1000]
  calls=[x['ms'] for x in bulk if x['kind']=='http' and x['operation']=='bulk' and r['started']<=x['start'] and x['end']<=r['queryEnded']]
  row={k:r[k] for k in ['condition','variant','started','queryEnded','queueBefore','queueAfter','indexed_during_window','indexed_per_second','created','cleanup_ms','contextSamples']}
  row.update(seconds=seconds,requests_per_second=103/seconds,latency={k:stat([x[k] for x in s]) for k in ['client_ms','took_ms','response_bytes','hits']},pit_create_ms=stat([x['create_ms'] for x in r['samples'] if x['create_ms']>0]),pit_close_ms=stat([x['close_ms'] for x in r['samples'] if x['close_ms']>0]) if r['variant']=='full-close' else None,ordered_ids_equal_reference=all(x['ids_hash']==reference for x in s),distinct_ordered_ids=len({x['ids_hash'] for x in s}),total_hits_values=list({json.dumps(x['total'],sort_keys=True) for x in s}),contexts={'before':a['indices']['search']['open_contexts'],'after_queries':b['indices']['search']['open_contexts'],'after_close':r['afterClose']['indices']['search']['open_contexts'],'sampled_max':max(x['open_contexts'] for x in r['contextSamples'])},opensearch_cpu_seconds=cpu,opensearch_cpu_mean_percent=100*cpu/seconds,heap_before=a['jvm']['mem']['heap_used_in_bytes'],heap_after=b['jvm']['mem']['heap_used_in_bytes'],heap_sampled_peak=max(x['heap'] for x in r['contextSamples']),gc={k:{field:v[field]-a['jvm']['gc']['collectors'][k][field] for field in ['collection_count','collection_time_in_millis']} for k,v in b['jvm']['gc']['collectors'].items()},index_counters=counters,thread_pools={k:{'before':a['thread_pool'][k],'after':b['thread_pool'][k]} for k in ['search','write']},container_resources=p2c.resources(rs),bulk_client_ms=stat(calls) if calls else None)
  assert row['contexts']['after_close']==0
  if r['variant']!='simple-sort':assert row['ordered_ids_equal_reference']
  rows.append(row)
 return {'root':str(path),'order':data['order'],'image':(root/'image-id.txt').read_text().strip(),'query_shape':json.loads((root/'query-shape.json').read_text()),'verification':json.loads((root/'ablation-verification.json').read_text()),'http_control':json.loads((root/'http-control.json').read_text()),'experiments':rows}
if __name__=='__main__':
 result={'schema':'palimora.performance.p2e1a.v1','baseline_commit':'e4acecb75f87e94f85725a5bb042354d20835956','p2e1a_complete':True,'p2e1_complete':False,'p2_complete':False,'runs':[run(pathlib.Path(x)) for x in sys.argv[1:]],'methodology':{'source_fixture':'/mnt/sdb/palimora-p2c-b1-20261109','works':11032,'conditions':['idle','backlog'],'workload_per_experiment':2000,'profile':'isolated Node projection process, batch16/prepare1/publish1; API and projection independent event loops, shared uncapped fixture container','query':'Captured from unchanged searchWorks(db, {}) on this database. No application changes. Only aggs removal, track_total_hits=false, or sort=[{id:asc}] in diagnostic copies.','samples':'103 queries per experiment; 3 predefined warmups, 100 measured. All raw samples retained in private ablations.json. PIT creation/closure summaries include warmups.','order':'Two independent cold clones of the same stopped PostgreSQL/OpenSearch fixture; reverse variant order in second run. Each experiment drains its backlog before next enqueue; no throughput cap. Same-source reindexing does not recreate identical segments between experiments.','timing':'Direct OpenSearch client includes response body consumption. took is nested server elapsed time, not CPU and not additive. PIT timings separate. Window throughput includes warmups, PIT operations and periodic stats calls; cleanup excluded.','http':'Original authenticated probe and existing per-request preload reused as idle control. Direct ablation timings are not HTTP API end-to-end or PostgreSQL durations.','pit':'retain opens 103 and closes together; close opens/closes each of 103; reuse opens one for 103 searches. Snapshots are not equivalent under real content changes.','resources':'Existing container sampler plus OpenSearch node counters at boundaries and every20 queries; no new resource-correlation campaign. Node CPU includes API/projection/probe in application container. CPU100%=one core. No Docker quotas, no cache drop, shared host.','response_bytes':'UTF-8 response body bytes, not total wire bytes.'},'limits':['Only the default unfiltered /works first-page query; no extrapolation to all full-text/filter shapes.','Different query speeds yield different indexing throughput and scheduler startup fractions; not a matched-load experiment. P2E.1b remains necessary.','Server CPU counters include concurrent indexing, stats and query work; not isolated query CPU.','PITs retain search snapshots/segments; same-source reindexing tests retention without changing content freshness.','No percentile subtraction used to apportion latency; observed variant distributions and server took are reported separately.','Frontend refetches every2s while indexing and uses cursors for paging; this rapid first-page loop has a different creation rate.','Two passes characterize observed variability, not statistical confidence or a definitive P2E.2 choice.']}
 result['validation']={'build':'npm run build passed','experiments':24,'measured_queries':2400,'warmup_queries':72,'ordered_ids':'All variants preserve the ordered first21 IDs except the deliberately different simple sort','pit_cleanup':'All experiments return open contexts to zero','baseline_preserved':'performance-p2e1.json and performance-search-spans.cjs unchanged'}
 result['findings']={'facets':'Largest reproducible intrinsic cost in this default query: removing facets reduces client and server elapsed time in both orders and both conditions. Backlog effect size is not matched-load causal attribution.','count':'No stable material improvement at idle; backlog variation prevents attributing its observed differences solely to total counting.','sort':'Simplified sort reduces idle latency but changes returned IDs/order, so it is not an equivalent product optimization.','pit':'Accumulation of contexts is directly observed (0 to103 to0); reuse holds1, immediate close leaves0 after each query. Reuse removes repeated opens, but changes snapshot freshness and its latency benefit varies. Segment/GC/indexing history prevents a clean causal estimate of retention cost.','next_phase':'P2E.1b matched-load/resource correlation still required; no definitive P2E.2 intervention selected.'}
 for run in result['runs']:
  assert len(run['experiments'])==12
  run['api_search_spans']=len(p2c.lines(pathlib.Path(run['root'])/'results/search-spans.jsonl'))
  for x in run['experiments']:
   assert x['latency']['hits']['min']==x['latency']['hits']['max']==21
   assert x['ordered_ids_equal_reference']==(x['variant']!='simple-sort')
 assert len({r['query_shape']['hash'] for r in result['runs']})==1
 print(json.dumps(result,indent=2))
